#include <bits/stdc++.h>using namespace std;using ll = long long; ll simulate(ll white, ll dark, bool startWhite){         ll size = 1;         int layers = 0;         bool whiteTurn = startWhite;          while (true)         {                  if (whiteTurn)                  {                           if (white < size)                                    break;                           white -= size;                  }                  else                  {                           if (dark < size)                                    break;                           dark -= size;                  }                  layers++;                  size <<= 1;                  whiteTurn = !whiteTurn;         }         return layers;} int32_t main(){         ios::sync_with_stdio(false);         cin.tie(nullptr);          ll t;         cin >> t;         while (t--)         {                  ll a, b;                  cin >> a >> b;                   ll ans = max(                      simulate(a, b, true),                      simulate(a, b, false));                   cout << ans << "\n";         }         return 0;}